package com.tuling.tim.server.web;
import com.tuling.tim.common.security.ConnectToken; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/demo") public class DemoLoginController { @Value("${tim.server.id:im-server-1}") String server; @Value("${tim.connect-token.secret:demo-only-change-me}") String secret; @PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,Object> b){long id=Long.parseLong(String.valueOf(b.get("userId")));if(id<=0)throw new IllegalArgumentException("userId must be positive");return Map.of("userId",id,"nickname",String.valueOf(b.getOrDefault("nickname","用户"+id)),"serverId",server,"token",ConnectToken.issue(id,server,600000,secret));} }
